%	},
%	postaction={decorate},
	line width = 1.2pt
	]
	({\xr*cos(\x)},{\yr*sin(\x)});

	\draw[draw=none, fill=deepskyblue] (axis cs: 2,0) circle (2.0pt) node[label = {[color = deepskyblue, below, xshift=0pt, yshift = -4pt]$A$} ]{};
	\draw[draw=none, fill=deepskyblue] (axis cs: -2,0) circle (2.0pt) node[label = {[color=deepskyblue, below, xshift=0pt,yshift = -4pt]$B$} ]{};


	\end{axis}

	\end{tikzpicture}

\end{document}

